if (!defined('ABSPATH')) exit;
class Baharaan_Commerce {
 const OPT='bhc_options';
 static function text_length($s){if(function_exists('mb_strlen'))return mb_strlen($s,'UTF-8');$ok=preg_match_all('/./us',(string)$s,$m);return $ok===false?strlen((string)$s):count($m[0]);}
 static function text_substr($s,$start,$length){if(function_exists('mb_substr'))return mb_substr($s,$start,$length,'UTF-8');$ok=preg_match_all('/./us',(string)$s,$m);return $ok===false?substr((string)$s,$start,$length):implode('',array_slice($m[0],$start,$length));}
 static function body_classes($classes){$o=self::opts();if(empty($o['motion_enabled']))$classes[]='bhc-motion-off';return $classes;}
 static function appearance_css(){$o=self::opts();$accent=sanitize_hex_color($o['accent_color'])?:'#087f72';echo '<style>:root{--bh-accent:'.$accent.';--green:'.$accent.';--green2:'.$accent.'}</style>';if(empty($o['motion_enabled']))echo '<style>html{scroll-behavior:auto!important}*,*:before,*:after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}</style>';}
 static function webp_output($formats,$filename,$mime_type){$o=self::opts();if(empty($o['webp_enabled'])||!function_exists('wp_image_editor_supports')||!wp_image_editor_supports(['mime_type'=>'image/webp']))return $formats;if(in_array($mime_type,['image/jpeg','image/png'],true))$formats[$mime_type]='image/webp';return $formats;}

 static function init(){ add_action('admin_menu',[__CLASS__,'menu']); add_action('admin_init',[__CLASS__,'settings']); add_action('init',[__CLASS__,'cpt']); add_filter('manage_bhc_lead_posts_columns',[__CLASS__,'lead_columns']); add_action('manage_bhc_lead_posts_custom_column',[__CLASS__,'lead_column'],10,2); add_filter('post_row_actions',[__CLASS__,'lead_actions'],10,2); add_action('admin_post_bhc_lead_stage',[__CLASS__,'lead_stage']); add_action('admin_enqueue_scripts',[__CLASS__,'admin_assets']); add_shortcode('baharaan_chat',[__CLASS__,'chat']); add_action('wp_footer',[__CLASS__,'floating_chat']); add_action('wp_enqueue_scripts',[__CLASS__,'assets']); add_action('wp_ajax_bhc_lead',[__CLASS__,'lead']); add_action('wp_ajax_nopriv_bhc_lead',[__CLASS__,'lead']); add_action('wp_ajax_bhc_assistant',[__CLASS__,'assistant']); add_action('wp_ajax_nopriv_bhc_assistant',[__CLASS__,'assistant']); add_action('wp_ajax_bhc_live_search',[__CLASS__,'live_search']); add_action('wp_ajax_nopriv_bhc_live_search',[__CLASS__,'live_search']); add_action('wp_ajax_bhc_wish_sync',[__CLASS__,'wish_sync']); add_action('admin_post_bhc_ai_test',[__CLASS__,'ai_test']); add_action('admin_post_bhc_reset',[__CLASS__,'reset_settings']); add_filter('wp_editor_set_quality',[__CLASS__,'image_quality'],10,2); add_action('add_meta_boxes_product',[__CLASS__,'box']); add_action('save_post_product',[__CLASS__,'save_product'],10,2); add_action('admin_post_bhc_prompt',[__CLASS__,'prompt']); add_action('admin_post_bhc_product_prompt',[__CLASS__,'product_prompt']); add_action('admin_post_bhc_export',[__CLASS__,'export_settings']); add_action('admin_post_bhc_import',[__CLASS__,'import_settings']); add_action('admin_post_bhc_generate_article',[__CLASS__,'generate_article']); add_action('admin_post_bhc_generate_product',[__CLASS__,'generate_product']); add_filter('image_editor_output_format',[__CLASS__,'webp_output'],10,3); add_filter('body_class',[__CLASS__,'body_classes']); add_action('wp_head',[__CLASS__,'appearance_css'],50); }
 static function opts(){return wp_parse_args(get_option(self::OPT,[]),['whatsapp'=>'','phone'=>'','telegram'=>'','instagram'=>'','bale'=>'','eitaa'=>'','email'=>get_option('admin_email'),'chat_greeting'=>'سلام! برای انتخاب لوازم خانه چه کمکی از دستم برمی‌آید؟','ai_enabled'=>false,'ai_endpoint'=>'https://openrouter.ai/api/v1/chat/completions','ai_model'=>'openai/gpt-4o-mini','ai_key'=>'','webp_enabled'=>true,'image_quality'=>82,'home_notice'=>'','support_hours'=>'','home_sections'=>['categories','featured','brands','editorial','journal','service'],'hero_title'=>'خانه‌ای هوشمندتر، زندگی راحت‌تر','hero_subtitle'=>'مشخصات و قیمت را از کاتالوگ واقعی فروشگاه ببینید.','hero_cta_label'=>'شروع خرید','hero_cta_url'=>'','hero_secondary_label'=>'دیدن پیشنهادها','hero_product_id'=>0,'footer_intro'=>'انتخاب لوازم خانه با اطلاعات محصول ثبت‌شده در فروشگاه.','show_compare'=>true,'show_wishlist'=>true,'show_rating'=>true,'sticky_buy'=>true,'accent_color'=>'#087f72','motion_enabled'=>true]);}
 static function api_endpoint($url){$url=esc_url_raw(trim((string)$url),['https']);$parts=wp_parse_url($url);if(!$url||!is_array($parts)||strtolower($parts['scheme']??'')!=='https'||empty($parts['host'])||!wp_http_validate_url($url))return 'https://openrouter.ai/api/v1/chat/completions';return $url;}
 static function image_quality($quality,$mime_type){$o=self::opts();return max(50,min(95,absint($o['image_quality']??82)));}
 static function product_payload($p){if(!$p)return null;$id=$p->get_id();$attrs=[];foreach($p->get_attributes() as $a){$vals=$a->is_taxonomy()?wc_get_product_terms($id,$a->get_name(),['fields'=>'names']):$a->get_options();if($vals)$attrs[wc_attribute_label($a->get_name())]=implode('، ',array_map('sanitize_text_field',$vals));}return ['id'=>$id,'title'=>$p->get_name(),'url'=>get_permalink($id),'image'=>get_the_post_thumbnail_url($id,'woocommerce_thumbnail')?:wc_placeholder_img_src(),'price'=>wp_strip_all_tags($p->get_price_html()),'sku'=>$p->get_sku(),'stock'=>$p->is_in_stock()?'موجود':'ناموجود','specs'=>$attrs];}
 static function live_search(){check_ajax_referer('bhc_public','nonce');if(!function_exists('wc_get_products'))wp_send_json_success(['items'=>[]]);$q=sanitize_text_field(wp_unslash($_GET['q']??''));if(self::text_length($q)<2||self::text_length($q)>80)wp_send_json_success(['items'=>[]]);$products=wc_get_products(['status'=>'publish','limit'=>6,'s'=>$q,'return'=>'objects']);if(!$products)$products=wc_get_products(['status'=>'publish','limit'=>4,'sku'=>$q,'return'=>'objects']);$items=[];foreach($products as $product){$items[]=['title'=>$product->get_name(),'url'=>get_permalink($product->get_id()),'image'=>get_the_post_thumbnail_url($product->get_id(),'woocommerce_thumbnail')?:wc_placeholder_img_src(),'price'=>wp_strip_all_tags($product->get_price_html()),'stock'=>$product->is_in_stock()?'موجود':'ناموجود'];}wp_send_json_success(['items'=>$items]);}
 static function wish_sync(){if(!is_user_logged_in())wp_send_json_error(['message'=>'ورود لازم است.'],401);check_ajax_referer('bhc_saved','nonce');$uid=get_current_user_id();if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['ids'])){$ids=json_decode(wp_unslash($_POST['ids']),true);if(!is_array($ids))$ids=[];$ids=array_values(array_unique(array_filter(array_map('absint',$ids))));$ids=array_slice($ids,0,100);$valid=[];foreach($ids as $id){$p=wc_get_product($id);if($p&&$p->get_status()==='publish')$valid[]=$id;}update_user_meta($uid,'_bhc_wishlist_ids',$valid);}else{$valid=array_values(array_filter(array_map('absint',(array)get_user_meta($uid,'_bhc_wishlist_ids',true))));}$items=[];foreach($valid as $id){$p=wc_get_product($id);$payload=self::product_payload($p);if($payload)$items[]=$payload;}wp_send_json_success(['items'=>$items]);}
 static function reset_settings(){if(!current_user_can('manage_options'))wp_die('دسترسی مجاز نیست');check_admin_referer('bhc_reset');delete_option(self::OPT);delete_option('bhc_ai_usage');wp_safe_redirect(admin_url('admin.php?page=baharaan-commerce&bhc_reset=1'));exit;}
 static function ai_test(){if(!current_user_can('manage_options'))wp_die('دسترسی مجاز نیست');check_admin_referer('bhc_ai_test');$o=self::opts();if(empty($o['ai_enabled'])||empty($o['ai_key']))$state='ابتدا پاسخ‌گویی را فعال و کلید را وارد کنید.';else{$endpoint=self::api_endpoint($o['ai_endpoint']??'');$resp=wp_safe_remote_post($endpoint,['timeout'=>25,'headers'=>['Authorization'=>'Bearer '.$o['ai_key'],'Content-Type'=>'application/json'],'body'=>wp_json_encode(['model'=>$o['ai_model'],'messages'=>[['role'=>'user','content'=>'Reply only OK']],'max_tokens'=>3,'temperature'=>0])]);$code=is_wp_error($resp)?0:wp_remote_retrieve_response_code($resp);$body=is_wp_error($resp)?[]:json_decode(wp_remote_retrieve_body($resp),true);if($code>=200&&$code<300&&isset($body['choices'][0]['message']['content']))$state='اتصال موفق — مدل '.$o['ai_model'].' پاسخ داد.';else$state='اتصال ناموفق (HTTP '.intval($code).'). مدل، اعتبار کلید و اعتبار حساب را بررسی کنید.';}set_transient('bhc_ai_test_'.get_current_user_id(),$state,MINUTE_IN_SECONDS);wp_safe_redirect(admin_url('admin.php?page=baharaan-commerce&bhc_ai_test=1'));exit;}
 static function export_settings(){if(!current_user_can('manage_options'))wp_die('دسترسی مجاز نیست');check_admin_referer('bhc_export');$o=self::opts();$hero=absint($o['hero_product_id']??0);$hero_product=$hero&&function_exists('wc_get_product')?wc_get_product($hero):null;$o['_hero_product_sku']=$hero_product?$hero_product->get_sku():'';unset($o['ai_key'],$o['hero_product_id']);$o['_exported_at']=gmdate('c');$o['_format']='baharaan-commerce-settings-v1';nocache_headers();header('Content-Type: application/json; charset=utf-8');header('Content-Disposition: attachment; filename=baharaan-settings-'.gmdate('Ymd').'.json');echo wp_json_encode($o,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
 static function import_settings(){if(!current_user_can('manage_options'))wp_die('دسترسی مجاز نیست');check_admin_referer('bhc_import');if(empty($_FILES['settings_file']['tmp_name'])||($_FILES['settings_file']['error']??UPLOAD_ERR_OK)!==UPLOAD_ERR_OK)wp_die('بارگذاری فایل تنظیمات انجام نشد');if((int)($_FILES['settings_file']['size']??0)>524288)wp_die('اندازه فایل باید کمتر از ۵۱۲ کیلوبایت باشد');$raw=file_get_contents($_FILES['settings_file']['tmp_name']);$data=json_decode($raw,true);if(!is_array($data)||($data['_format']??'')!=='baharaan-commerce-settings-v1')wp_die('ساختار فایل معتبر نیست');$old=self::opts();$allowed=['whatsapp','phone','telegram','instagram','bale','eitaa','email','chat_greeting','ai_enabled','ai_endpoint','ai_model','webp_enabled','image_quality','home_notice','support_hours','home_sections','hero_title','hero_subtitle','hero_cta_label','hero_cta_url','hero_secondary_label','hero_product_id','footer_intro','show_compare','show_wishlist','show_rating','sticky_buy','accent_color','motion_enabled'];$next=[];foreach($allowed as $k)if(array_key_exists($k,$data))$next[$k]=$data[$k];foreach(['whatsapp','phone','chat_greeting','ai_model','hero_title','hero_subtitle','hero_cta_label','hero_secondary_label','footer_intro','home_notice','support_hours'] as $k)if(isset($next[$k]))$next[$k]=sanitize_text_field($next[$k]);if(isset($next['ai_endpoint']))$next['ai_endpoint']=self::api_endpoint($next['ai_endpoint']);foreach(['telegram','instagram','bale','eitaa'] as $k)if(isset($next[$k]))$next[$k]=esc_url_raw($next[$k]);if(isset($next['email']))$next['email']=sanitize_email($next['email']);if(isset($next['hero_cta_url']))$next['hero_cta_url']=esc_url_raw($next['hero_cta_url']);if(!empty($data['_hero_product_sku'])&&function_exists('wc_get_product_id_by_sku'))$next['hero_product_id']=absint(wc_get_product_id_by_sku(sanitize_text_field($data['_hero_product_sku'])));elseif(array_key_exists('_hero_product_sku',$data))$next['hero_product_id']=0;if(isset($next['accent_color']))$next['accent_color']=sanitize_hex_color($next['accent_color'])?:$old['accent_color'];if(isset($next['image_quality']))$next['image_quality']=max(50,min(95,absint($next['image_quality'])));if(isset($next['home_sections'])&&!is_array($next['home_sections']))$next['home_sections']=[];if(isset($next['home_sections']))$next['home_sections']=array_values(array_intersect(array_map('sanitize_key',$next['home_sections']),['categories','featured','brands','editorial','journal','service']));foreach(['ai_enabled','webp_enabled','motion_enabled','show_compare','show_wishlist','show_rating','sticky_buy'] as $k)if(isset($next[$k]))$next[$k]=(bool)$next[$k];$next['ai_key']=$old['ai_key'];update_option(self::OPT,wp_parse_args($next,$old),false);wp_safe_redirect(add_query_arg('bhc_imported','1',admin_url('admin.php?page=baharaan-commerce')));exit;}
 static function ai_call($system,$prompt,$max=1800){$o=self::opts();if(empty($o['ai_enabled'])||empty($o['ai_key']))return new WP_Error('bhc_ai_disabled','ابتدا OpenRouter و کلید API را در تنظیمات فعال کنید.');$uid=get_current_user_id();$rk='bhc_ai_gen_'.($uid?:'admin');$used=(int)get_transient($rk);if($used>=10)return new WP_Error('bhc_ai_rate','سقف ۱۰ درخواست تولید محتوا در یک ساعت پر شده است.');set_transient($rk,$used+1,HOUR_IN_SECONDS);$endpoint=self::api_endpoint($o['ai_endpoint']??'');$resp=wp_safe_remote_post($endpoint,['timeout'=>45,'headers'=>['Authorization'=>'Bearer '.$o['ai_key'],'Content-Type'=>'application/json','HTTP-Referer'=>home_url('/'),'X-Title'=>get_bloginfo('name')],'body'=>wp_json_encode(['model'=>$o['ai_model'],'messages'=>[['role'=>'system','content'=>$system],['role'=>'user','content'=>$prompt]],'temperature'=>0.55,'max_tokens'=>$max])]);if(is_wp_error($resp))return $resp;$body=json_decode(wp_remote_retrieve_body($resp),true);$text=$body['choices'][0]['message']['content']??'';if(!$text)return new WP_Error('bhc_ai_response','مدل پاسخ متنی معتبر برنگرداند.');$usage=$body['usage']??[];update_option('bhc_ai_usage',['model'=>sanitize_text_field($o['ai_model']),'prompt_tokens'=>absint($usage['prompt_tokens']??0),'completion_tokens'=>absint($usage['completion_tokens']??0),'updated_at'=>current_time('mysql')],false);return sanitize_textarea_field($text);}
 static function generate_article(){if(!current_user_can('edit_posts'))wp_die('دسترسی مجاز نیست');check_admin_referer('bhc_article');$topic=sanitize_text_field(wp_unslash($_POST['topic']??''));$keywords=sanitize_text_field(wp_unslash($_POST['keywords']??''));$tone=sanitize_text_field(wp_unslash($_POST['tone']??'راهنمایی تخصصی و صادقانه'));if(!$topic)wp_die('موضوع مقاله ضروری است');$content=self::ai_call('نویسنده فارسی فروشگاه لوازم خانگی. فقط متن مقاله‌ی کاربردی و دقیق بساز. از ساختن عدد، مشخصات فنی، ادعای گارانتی یا قیمت پرهیز کن؛ موارد نیازمند تایید را با [نیازمند بررسی] مشخص کن. عنوان و میان‌تیترهای ساده بده.','موضوع: '.$topic.'\nکلیدواژه‌ها: '.$keywords.'\nلحن: '.$tone.'\nحدود ۹۰۰ کلمه؛ شامل مقدمه، راهنمای خرید مرحله‌ای، نکات نگهداری و پرسش‌های پرتکرار. از تکرار مصنوعی کلیدواژه بپرهیز.',2200);if(is_wp_error($content))wp_die(esc_html($content->get_error_message()));$title=$topic;$id=wp_insert_post(['post_type'=>'post','post_status'=>'draft','post_title'=>$title,'post_content'=>wp_kses_post(wpautop($content))]);if(is_wp_error($id)||!$id)wp_die('ثبت پیش‌نویس ناموفق بود');wp_safe_redirect(admin_url('post.php?post='.$id.'&action=edit&bhc_draft=1'));exit;}
 static function generate_product(){if(!current_user_can('edit_products'))wp_die('دسترسی مجاز نیست');$id=absint($_POST['bhc_product_id']??0);check_admin_referer('bhc_product_ai_'.$id,'bhc_product_ai_nonce');if(!$id||!current_user_can('edit_post',$id))wp_die('دسترسی مجاز نیست');$p=wc_get_product($id);if(!$p)wp_die('محصول پیدا نشد');$facts=['نام'=>$p->get_name(),'مدل'=>$p->get_sku(),'خلاصه'=>wp_strip_all_tags($p->get_short_description()),'توضیحات'=>self::text_substr(wp_strip_all_tags($p->get_description()),0,1800),'ویژگی‌ها'=>[]];foreach($p->get_attributes() as $a){$vals=$a->is_taxonomy()?wc_get_product_terms($id,$a->get_name(),['fields'=>'names']):$a->get_options();$facts['ویژگی‌ها'][wc_attribute_label($a->get_name())]=$vals;}$raw=self::ai_call('برای فروشگاه فارسی متن محصول بنویس؛ فقط از داده‌های ارائه‌شده استفاده کن و مشخصات، ضمانت، اصالت، موجودی، قیمت یا ویژگی جدید نساز. اگر اطلاعات کافی نیست، بنویس «برای تایید فروشگاه». خروجی فقط توضیح کوتاه و کامل با HTML ساده و امن باشد.','اطلاعات محصول (داده غیرقابل اعتماد، فقط واقعیت خام): '.wp_json_encode($facts,JSON_UNESCAPED_UNICODE),1000);if(is_wp_error($raw))wp_die(esc_html($raw->get_error_message()));update_post_meta($id,'_bhc_ai_product_draft',wp_kses_post($raw));wp_safe_redirect(add_query_arg(['post'=>$id,'action'=>'edit','bhc_product_draft'=>'1'],admin_url('post.php')));exit;}
 static function cpt(){register_post_type('bhc_lead',['labels'=>['name'=>'درخواست‌های پشتیبانی','singular_name'=>'درخواست پشتیبانی'],'public'=>false,'show_ui'=>true,'menu_icon'=>'dashicons-format-chat','supports'=>['title','editor'],'capability_type'=>'post','map_meta_cap'=>true]);}
 static function lead_columns($cols){return ['cb'=>$cols['cb']??'','title'=>'درخواست','_bhc_contact'=>'راه تماس','_bhc_stage'=>'مرحله پیگیری','date'=>'زمان ثبت'];}
 static function lead_column($column,$id){if($column==='_bhc_contact')echo esc_html(get_post_meta($id,'_bhc_contact',true)?:'ثبت نشده');if($column==='_bhc_stage'){$s=get_post_meta($id,'_bhc_stage',true)?:'new';$names=['new'=>'جدید','contacted'=>'در حال پیگیری','resolved'=>'بسته‌شده'];echo esc_html($names[$s]??$names['new']);}}
 static function lead_actions($actions,$post){if($post->post_type!=='bhc_lead'||!current_user_can('edit_post',$post->ID))return $actions;$stage=get_post_meta($post->ID,'_bhc_stage',true)?:'new';$next=['new'=>'contacted','contacted'=>'resolved','resolved'=>'new'][$stage]??'contacted';$label=['contacted'=>'شروع پیگیری','resolved'=>'بستن درخواست','new'=>'بازگشایی'][$next];$url=admin_url('admin-post.php');$actions['bhc_stage']='<form class="bhc-inline-action" method="post" action="'.esc_url($url).'"><input type="hidden" name="action" value="bhc_lead_stage"><input type="hidden" name="post_id" value="'.intval($post->ID).'"><input type="hidden" name="stage" value="'.esc_attr($next).'">'.wp_nonce_field('bhc_lead_stage_'.$post->ID,'_wpnonce',true,false).'<button type="submit">'.esc_html($label).'</button></form>';return $actions;}
 static function lead_stage(){if(!current_user_can('edit_posts'))wp_die('دسترسی مجاز نیست');$id=absint($_POST['post_id']??0);$stage=sanitize_key($_POST['stage']??'');check_admin_referer('bhc_lead_stage_'.$id);if($id&&in_array($stage,['new','contacted','resolved'],true))update_post_meta($id,'_bhc_stage',$stage);wp_safe_redirect(admin_url('edit.php?post_type=bhc_lead'));exit;}
 static function admin_assets($hook){if($hook==='toplevel_page_baharaan-commerce'||($hook==='edit.php'&&($_GET['post_type']??'')==='bhc_lead'))wp_enqueue_style('bhc-admin',plugin_dir_url(__FILE__).'assets/admin.css',[],'1.3.0');}
 static function jalali_date($timestamp){$timestamp=(int)$timestamp;if(class_exists('IntlDateFormatter')){$fmt=new IntlDateFormatter('fa_IR@calendar=persian',IntlDateFormatter::NONE,IntlDateFormatter::NONE,'Asia/Tehran',IntlDateFormatter::TRADITIONAL,'yyyy/MM/dd HH:mm');$value=$fmt->format($timestamp);if($value!==false)return $value;}return wp_date('Y/m/d H:i',$timestamp,new DateTimeZone('Asia/Tehran')).' (میلادی)';}
 static function dashboard(){
  $lead_q=new WP_Query(['post_type'=>'bhc_lead','post_status'=>'private','posts_per_page'=>5,'orderby'=>'date','order'=>'DESC','no_found_rows'=>false]);$lead_count=(int)$lead_q->found_posts;$open_q=new WP_Query(['post_type'=>'bhc_lead','post_status'=>'private','posts_per_page'=>1,'meta_query'=>[['key'=>'_bhc_stage','value'=>'resolved','compare'=>'!=']],'fields'=>'ids']);$open=(int)$open_q->found_posts;
  $orders=[];$order_count=0;$sales=0;$since=current_datetime()->modify('-30 days')->format('Y-m-d H:i:s');if(function_exists('wc_get_orders')){$orders=wc_get_orders(['status'=>['processing','completed'],'limit'=>5,'orderby'=>'date','order'=>'DESC','date_created'=>'>='.$since,'return'=>'objects']);$count_query=wc_get_orders(['status'=>['processing','completed'],'limit'=>1,'paginate'=>true,'date_created'=>'>='.$since]);$order_count=is_object($count_query)&&isset($count_query->total)?(int)$count_query->total:count($orders);foreach($orders as $order)$sales+=(float)$order->get_total();}
  echo '<section class="bhc-dashboard" aria-labelledby="bhc-dashboard-title"><div class="bhc-dash-head"><div><span class="bhc-eyebrow">BAHARAAN / CONTROL CENTER</span><h2 id="bhc-dashboard-title">نمای کلی فروشگاه</h2><p>سلام، وضعیت امروز فروشگاه را از همین‌جا پیگیری کن.</p></div><time>'.esc_html(self::jalali_date(current_datetime()->getTimestamp())).'</time></div>';
  echo '<div class="bhc-admin-metrics"><article class="is-accent"><span class="bhc-metric-icon">↗</span><small>سفارش‌های ۳۰ روز اخیر</small><b>'.number_format_i18n($order_count).'</b><span>در انتظار پردازش و تکمیل‌شده</span></article><article><span class="bhc-metric-icon">ت</span><small>درخواست‌های باز پشتیبانی</small><b>'.number_format_i18n($open).'</b><span>از مجموع '.number_format_i18n($lead_count).' درخواست</span></article><article><span class="bhc-metric-icon">ر</span><small>فروش ۵ سفارش اخیر</small><b>'.esc_html(function_exists('wc_price')?wp_strip_all_tags(wc_price($sales)):'—').'</b><span>جمع آخرین سفارش‌های قابل‌نمایش در این بازه</span></article><article><span class="bhc-metric-icon">◇</span><small>وضعیت فروشگاه</small><b class="bhc-metric-status">'.(function_exists('wc_get_orders')?'آماده‌ی بررسی':'ووکامرس غیرفعال').'</b><span>اطلاعات زنده از وردپرس و ووکامرس</span></article></div>';
  echo '<nav class="bhc-quick-actions" aria-label="دسترسی سریع"><a href="'.esc_url(admin_url('post-new.php?post_type=product')).'"><b>＋</b><span>افزودن محصول</span><small>ثبت کالا و مشخصات</small></a><a href="'.esc_url(admin_url('edit.php?post_type=product')).'"><b>▤</b><span>مدیریت محصولات</span><small>قیمت، موجودی و تنوع‌ها</small></a><a href="'.esc_url(admin_url('admin.php?page=wc-orders')).'"><b>◷</b><span>سفارش‌ها</span><small>پیگیری و پردازش خریدها</small></a><a href="'.esc_url(admin_url('edit.php?post_type=bhc_lead')).'"><b>✉</b><span>پشتیبانی مشتریان</span><small>'.number_format_i18n($open).' درخواست باز</small></a></nav>';
  echo '<div class="bhc-dash-columns"><section class="bhc-dash-panel"><header><div><span class="bhc-eyebrow">COMMERCE</span><h3>آخرین سفارش‌ها</h3></div><a href="'.esc_url(admin_url('admin.php?page=wc-orders')).'">مشاهده‌ی همه ←</a></header>';
  if($orders){echo '<div class="bhc-table-scroll"><table><thead><tr><th>سفارش</th><th>مشتری</th><th>مبلغ</th><th>وضعیت</th><th>زمان</th></tr></thead><tbody>';foreach($orders as $order){$edit=method_exists($order,'get_edit_order_url')?$order->get_edit_order_url():admin_url('post.php?post='.$order->get_id().'&action=edit');$name=trim($order->get_billing_first_name().' '.$order->get_billing_last_name())?:'مشتری فروشگاه';$created=$order->get_date_created();echo '<tr><td><a href="'.esc_url($edit).'">#'.intval($order->get_order_number()).'</a></td><td>'.esc_html($name).'</td><td>'.wp_kses_post($order->get_formatted_order_total()).'</td><td><span class="bhc-order-status">'.esc_html(wc_get_order_status_name('wc-'.$order->get_status())).'</span></td><td>'.esc_html($created?self::jalali_date($created->getTimestamp()):'—').'</td></tr>'; }echo '</tbody></table></div>';}else echo '<p class="bhc-empty-state">در بازه‌ی اخیر سفارشی برای نمایش وجود ندارد.</p>';
  echo '</section><section class="bhc-dash-panel"><header><div><span class="bhc-eyebrow">CUSTOMER CARE</span><h3>درخواست‌های پشتیبانی</h3></div><a href="'.esc_url(admin_url('edit.php?post_type=bhc_lead')).'">مدیریت درخواست‌ها ←</a></header>';
  if($lead_q->have_posts()){echo '<ul class="bhc-lead-list">';while($lead_q->have_posts()){$lead_q->the_post();$lid=get_the_ID();$stage=get_post_meta($lid,'_bhc_stage',true)?:'new';$labels=['new'=>'جدید','contacted'=>'در حال پیگیری','resolved'=>'بسته‌شده'];$contact=get_post_meta($lid,'_bhc_contact',true);echo '<li><span class="bhc-lead-avatar">'.esc_html(self::text_substr(get_the_title(),0,1)).'</span><div><a href="'.esc_url(get_edit_post_link($lid)).'"><b>'.esc_html(get_the_title()).'</b></a><small>'.esc_html($contact?:'بدون راه تماس').' · '.esc_html(self::jalali_date(get_post_timestamp($lid))).'</small></div><span class="bhc-lead-stage stage-'.esc_attr($stage).'">'.esc_html($labels[$stage]??$labels['new']).'</span></li>'; }echo '</ul>';wp_reset_postdata();}else echo '<p class="bhc-empty-state">هنوز درخواستی ثبت نشده است.</p>';
  echo '</section></div><p class="bhc-dash-foot">آمار فروش برای ۳۰ روز اخیر است. مبلغ کارت، جمع ۵ سفارش آخر همین بازه را نشان می‌دهد؛ برای گزارش مالی کامل، گزارش‌های خود ووکامرس را باز کنید.</p></section>';
 }

